import * as THREE from './vendor/three.module.js';
import { RoundedBoxGeometry } from './vendor/RoundedBoxGeometry.js';
import { OrbitControls } from './vendor/OrbitControls.js';
const palette=['#eee7d8','#477a9c','#d8ac66','#b9d4e1','#753644','#3d4142'];
const finishes=['#b8bdbb','#d9d2bf','#253b53','#252725'];
const labels=[['Esc','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','F11','F12','Del'],['~ Ё','1 !','2 @','3 #','4 $','5 %','6 ^','7 &','8 *','9 (','0 )','− _','= +','Backspace'],['Tab','Q Й','W Ц','E У','R К','T Е','Y Н','U Г','I Ш','O Щ','P З','[ Х','] Ъ','\\'],['Caps','A Ф','S Ы','D В','F А','G П','H Р','J О','K Л','L Д','; Ж','’ Э','Enter'],['Shift','Z Я','X Ч','C С','V М','B И','N Т','M Ь',', Б','. Ю','/ ?','Shift'],['Ctrl','Win','Alt','SPACE','Alt','Fn','Ctrl']];
const unit=.017;
function layout(){let keys=[];labels.forEach((row,r)=>{let x=27;row.forEach((label,i)=>{let w=r===0?51:r===1?(i===13?100:48):r===2?(i===0?70:i===13?78:48):r===3?(i===0?83:i===12?117:48):r===4?(i===0?107:i===11?90:48):(label==='SPACE'?275:61);keys.push({label,w:w*unit,d:(r===0?43:44)*unit,x:(x+w/2-450)*unit,z:([28,82,132,182,232,282][r]+22-189)*unit});x+=w+5;});});['Home','PgUp','PgDn'].forEach((label,i)=>keys.push({label,w:42*unit,d:43*unit,x:855*unit-450*unit,z:(88+i*49+21-189)*unit}));keys.push({label:'↑',w:44*unit,d:43*unit,x:(778+22-450)*unit,z:(235+21-189)*unit});['←','↓','→'].forEach((label,i)=>keys.push({label,w:44*unit,d:43*unit,x:(726+i*51+22-450)*unit,z:(284+21-189)*unit}));return keys;}
function topGeometry(w,d){const n=16,pos=[],uv=[],indices=[],radius=.07;for(let j=0;j<=n;j++){let z=(j/n-.5)*d;const edge=Math.max(0,Math.abs(z)-(d/2-radius));const limit=w/2-radius+Math.sqrt(Math.max(0,radius*radius-edge*edge));for(let i=0;i<=n;i++){let x=(i/n-.5)*2*limit;const dish=.055*(1-(x/(w/2))**2)*(1-(z/(d/2))**2);pos.push(x,.225-dish,z);uv.push(x/w+.5,1-j/n);}}for(let j=0;j<n;j++)for(let i=0;i<n;i++){const a=j*(n+1)+i;indices.push(a,a+n+1,a+1,a+1,a+n+1,a+n+2);}const edge=[];for(let i=0;i<=n;i++)edge.push(i);for(let j=1;j<=n;j++)edge.push(j*(n+1)+n);for(let i=n-1;i>=0;i--)edge.push(n*(n+1)+i);for(let j=n-1;j>0;j--)edge.push(j*(n+1));const lower=pos.length/3;edge.forEach(k=>{pos.push(pos[k*3]*1.04,.10,pos[k*3+2]*1.04);uv.push(uv[k*2],uv[k*2+1]);});edge.forEach((k,i)=>{const j=(i+1)%edge.length;indices.push(k,edge[j],lower+i,edge[j],lower+j,lower+i);});const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();return g;}
function legendTexture(label,w,d,color,mode){const canvas=document.createElement('canvas');canvas.width=Math.min(1024,Math.round(160*w/d));canvas.height=160;const c=canvas.getContext('2d'),W=canvas.width,H=160;c.fillStyle=color;c.fillRect(0,0,W,H);if(mode==='blank')return new THREE.CanvasTexture(canvas);const ink=['#477a9c','#753644','#3d4142'].includes(color)?'#f4eddc':'#202321';c.fillStyle=ink;const [en,ru]=label.split(' ');if(label==='SPACE'){c.beginPath();c.moveTo(W*.04,H*.76);c.bezierCurveTo(W*.25,H*.38,W*.34,H*1.1,W*.75,H*.42);c.bezierCurveTo(W*1.03,-H*.1,W*.99,H*.77,W*.88,H*.81);c.bezierCurveTo(W*.7,H*.86,W*.35,H*.76,W*.04,H*.76);c.fill();c.fillStyle=color;c.beginPath();c.ellipse(W*.85,H*.55,W*.045,H*.095,-.2,0,Math.PI*2);c.fill();}else{c.font=`600 ${en.length>5?20:en.length>3?25:34}px Arial`;c.textBaseline='top';c.fillText(en,18,18);if(ru&&mode==='dual'){c.font='600 31px Arial';c.textAlign='right';c.fillText(ru,W-17,H-57);c.textAlign='left';}if(['Esc','Tab','Caps','Shift','Enter','Backspace','F4','F8','F12','Del','PgUp','PgDn','←','↓','→','↑'].includes(label)){c.beginPath();if(label==='Enter'){c.moveTo(W*.48,H*.83);c.bezierCurveTo(W*.8,H*.75,W*.91,H*.49,W*.95,H*.25);c.bezierCurveTo(W*1.01,H*.93,W*.93,H*.92,W*.48,H*.83);}else{c.moveTo(W*.25,H*.78);c.bezierCurveTo(W*.58,H*.84,W*.79,H*.7,W*.88,H*.56);c.bezierCurveTo(W*.97,H*.96,W*.57,H*.95,W*.25,H*.78);}c.fill();}}
const t=new THREE.CanvasTexture(canvas);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=4;return t;}
class KeyboardViewer{
 constructor(host,hero=false){this.host=host;this.hero=hero;this.keyMeshes=[];this.state={c:0,k:3,l:'dual',f:'satin'};this.active=true;this.build();}
 build(){const host=this.host;this.stage=document.createElement('div');this.stage.className='viewer-stage';this.stage.setAttribute('role','img');this.stage.setAttribute('aria-label','Interactive 3D keyboard. Drag to rotate, or use the view buttons.');this.stage.tabIndex=0;host.append(this.stage);try{this.renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});}catch{this.stage.remove();return;}
this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));this.renderer.setClearColor(0x000000,0);this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.0;this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.stage.append(this.renderer.domElement);this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(35,1,.1,150);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enablePan=false;this.controls.enableDamping=false;this.controls.minDistance=12;this.controls.maxDistance=36;this.controls.minPolarAngle=.08;this.controls.maxPolarAngle=1.42;this.controls.enableZoom=false;this.controls.target.set(0,.45,0);this.controls.addEventListener('change',()=>this.draw());
this.scene.add(new THREE.HemisphereLight(0xfffcf2,0x647263,2));const key=new THREE.DirectionalLight(0xfff6e7,2.5);key.position.set(-8,15,7);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-11;key.shadow.camera.right=11;key.shadow.camera.top=8;key.shadow.camera.bottom=-8;key.shadow.bias=-.001;key.shadow.normalBias=.02;key.shadow.radius=3;this.scene.add(key);const fill=new THREE.DirectionalLight(0xe0ebff,1.5);fill.position.set(9,6,-8);this.scene.add(fill);
this.caseMaterial=new THREE.MeshStandardMaterial({color:finishes[0],metalness:.55,roughness:.4});const body=new THREE.Mesh(new RoundedBoxGeometry(15.3,.62,6.2,4,.18),this.caseMaterial);body.position.y=.12;body.castShadow=true;body.receiveShadow=true;this.scene.add(body);
const seam=new THREE.Mesh(new RoundedBoxGeometry(15.22,.035,6.12,3,.16),new THREE.MeshStandardMaterial({color:'#1d251e',roughness:.8}));seam.position.y=-.08;this.scene.add(seam);
const deck=new THREE.Mesh(new RoundedBoxGeometry(14.98,.12,5.9,3,.12),this.caseMaterial);deck.position.y=.45;deck.receiveShadow=true;this.scene.add(deck);
this.keyMaterial=new THREE.MeshStandardMaterial({color:palette[3],roughness:.62,metalness:0});
for(const item of layout()){const group=new THREE.Group();group.position.set(item.x,.77,item.z);const base=new THREE.Mesh(new RoundedBoxGeometry(item.w-.025,.32,item.d-.025,3,.065),this.keyMaterial);base.castShadow=true;base.receiveShadow=true;group.add(base);const cap=new THREE.Mesh(topGeometry(item.w-.12,item.d-.10),new THREE.MeshStandardMaterial({map:legendTexture(item.label,item.w,item.d,palette[3],'dual'),roughness:.7,side:THREE.DoubleSide}));cap.receiveShadow=true;group.add(cap);this.scene.add(group);this.keyMeshes.push({item,group,cap});if(['F А','J О'].includes(item.label)){const nub=new THREE.Mesh(new RoundedBoxGeometry(.13,.025,.025,1,.01),this.keyMaterial);nub.position.set(0,.235,.19);group.add(nub);}}
const knob=new THREE.Mesh(new THREE.CylinderGeometry(.39,.41,.35,48),new THREE.MeshStandardMaterial({color:'#181a18',roughness:.63,metalness:.2}));knob.position.set((854-450)*unit,.81,(45-189)*unit);knob.castShadow=true;knob.receiveShadow=true;this.scene.add(knob);const rim=new THREE.Mesh(new THREE.TorusGeometry(.397,.012,6,48),new THREE.MeshStandardMaterial({color:'#30332e',roughness:.6}));rim.rotation.x=Math.PI/2;rim.position.copy(knob.position);rim.position.y=.95;this.scene.add(rim);
const port=new THREE.Mesh(new RoundedBoxGeometry(.42,.12,.04,2,.04),new THREE.MeshStandardMaterial({color:'#121612'}));port.position.set(-4.7,.12,-3.105);this.scene.add(port);
for(const x of [-6.3,6.3])for(const z of [-2.3,2.3]){const foot=new THREE.Mesh(new RoundedBoxGeometry(.8,.11,.4,2,.09),new THREE.MeshStandardMaterial({color:'#252923',roughness:.95}));foot.position.set(x,-.24,z);this.scene.add(foot);}
const ground=new THREE.Mesh(new THREE.PlaneGeometry(60,60),new THREE.ShadowMaterial({opacity:.17}));ground.rotation.x=-Math.PI/2;ground.position.y=-.31;ground.receiveShadow=true;this.scene.add(ground);
this.addToolbar();this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(this.stage);this.stage.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const p=this.camera.position;const offset=p.clone().sub(this.controls.target),sph=new THREE.Spherical().setFromVector3(offset);if(e.key==='ArrowLeft')sph.theta-=.12;if(e.key==='ArrowRight')sph.theta+=.12;if(e.key==='ArrowUp')sph.phi=Math.max(.1,sph.phi-.1);if(e.key==='ArrowDown')sph.phi=Math.min(1.4,sph.phi+.1);p.copy(new THREE.Vector3().setFromSpherical(sph).add(this.controls.target));this.controls.update();this.draw();}});
this.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();host.classList.remove('has-3d');this.stage.hidden=true;this.toolbar.hidden=true;});host.classList.add('has-3d');this.view('angle');this.resize();this.update(this.hero?{c:0,k:3,l:'dual',f:'satin'}:globalThis.getKeyboardDesign?.());}
 addToolbar(){this.toolbar=document.createElement('div');this.toolbar.className='viewer-toolbar';this.toolbar.innerHTML='<span class="viewer-hint"><span class="live-dot"></span> 3D VIEW <span class="drag-hint">/ DRAG TO ROTATE</span></span><button class="viewer-reset" type="button" aria-label="Reset 3D angle">Reset angle ↺</button>';this.host.append(this.toolbar);this.toolbar.querySelector('button').addEventListener('click',()=>this.view('angle'));}

 view(type){this.currentView=type==='reset'?'angle':type;const width=this.stage.clientWidth;const mobile=width<500;const far=mobile?1.13:1;if(this.currentView==='top'){this.controls.target.set(0,.5,0);this.camera.position.set(0,26*far,.1);}else if(this.currentView==='detail'){this.controls.target.set(3.6,.6,-.8);this.camera.position.set(8,10,9);}else{this.controls.target.set(0,.45,0);this.camera.position.set(2.5*far,21*far,12*far);}this.controls.update();this.toolbar?.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===this.currentView)));this.draw();}
 update(state){if(!state||!this.renderer)return;const next=JSON.stringify(state);if(next===this.lastState)return;this.lastState=next;this.state=state;this.caseMaterial.color.set(finishes[state.c]);this.caseMaterial.metalness=state.c===0?.55:.28;this.caseMaterial.roughness=state.f==='brushed'?.6:.38;this.keyMaterial.color.set(palette[state.k]);for(const {item,cap} of this.keyMeshes){cap.material.map?.dispose();cap.material.map=legendTexture(item.label,item.w,item.d,palette[state.k],state.l);cap.material.needsUpdate=true;}this.draw();}
 resize(){if(!this.renderer)return;const w=this.stage.clientWidth,h=this.stage.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();if(this.currentView!=='detail'){const direction=this.camera.position.clone().sub(this.controls.target).normalize();this.camera.position.copy(this.controls.target).addScaledVector(direction,Math.max(12,28/this.camera.aspect));this.controls.update();}this.draw();}
 draw(){if(this.renderer)this.renderer.render(this.scene,this.camera);}
}
// Keep a straight product picture by default; create one 3D model only on request.
const instances=[];
const original=document.querySelector('#config-board');
if(original){const host=document.createElement('div');host.className='keyboard-studio picture-first';original.before(host);original.classList.add('studio-fallback');const modes=document.createElement('div');modes.className='preview-modes';modes.setAttribute('role','group');modes.setAttribute('aria-label','Keyboard preview');modes.innerHTML='<button type="button" data-mode="picture" aria-pressed="true">Straight picture</button><button type="button" data-mode="model" aria-pressed="false">3D view</button><span>EN + RU</span>';host.append(modes,original);let viewer=null;
function showMode(mode){if(mode==='model'&&!viewer){try{viewer=new KeyboardViewer(host,false);if(!viewer.renderer)throw Error('WebGL unavailable');instances.push(viewer);}catch(err){host.querySelector('.viewer-stage')?.remove();host.querySelector('.viewer-toolbar')?.remove();host.classList.remove('has-3d');viewer=null;const status=document.querySelector('#status');if(status)status.textContent='The 3D view is unavailable in this browser. Your keyboard picture is still available.';return;}}const model=mode==='model';host.classList.toggle('has-3d',model);if(viewer){viewer.stage.hidden=!model;viewer.toolbar.hidden=!model;if(model){viewer.resize();viewer.view('angle');viewer.update(globalThis.getKeyboardDesign?.());}}modes.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.mode==='model')===model)));const caption=document.querySelector('.art-caption span:last-child');if(caption)caption.textContent=model?'3D CONCEPT VIEW · EN + RU':'STRAIGHT PICTURE · EN + RU';}
modes.addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b)showMode(b.dataset.mode);});showMode('picture');}
let queued=false;function sync(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;const state=globalThis.getKeyboardDesign?.();if(state){const names=[['recap-case',['Silver aluminum','Ivory','Deep blue','Black'][state.c]],['recap-color',['Milk','Denim blue','Sand honey','Ice blue','Muted wine','Graphite'][state.k]],['recap-switch',{linear:'Linear',tactile:'Tactile',clicky:'Clicky'}[state.s]]];for(const [id,value] of names){const el=document.getElementById(id);if(el)el.textContent=value;}}instances.filter(v=>!v.hero).forEach(v=>v.update(state));});}document.addEventListener('click',sync);document.addEventListener('change',sync);

sync();
